import { useState } from "react";

export function DraggingState({
  label = "{{label}}",
  accent = "{{accent}}",
  force = {{force}},
  tilt = {{tilt}},
}) {
  const [live, setLive] = useState(false);
  const dragging = force || live;
  return (
    <div style={{ width: 260, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12 }}>
      <div
        draggable
        onDragStart={() => setLive(true)}
        onDragEnd={() => setLive(false)}
        style={{
          display: "flex", alignItems: "center", gap: 8, fontWeight: 600, padding: "14px 16px", borderRadius: 10,
          background: "#fff", border: "1.5px solid #24143020", cursor: dragging ? "grabbing" : "grab",
          opacity: dragging ? 0.5 : 1, transform: dragging ? `rotate(${tilt}deg) scale(1.03)` : "none",
          boxShadow: dragging ? "0 10px 20px rgba(36,20,48,.2)" : "none",
        }}
      >
        <svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true" style={{ color: accent, flexShrink: 0 }}>
          <circle cx="8" cy="6" r="2" fill="currentColor" /><circle cx="8" cy="12" r="2" fill="currentColor" /><circle cx="8" cy="18" r="2" fill="currentColor" />
          <circle cx="16" cy="6" r="2" fill="currentColor" /><circle cx="16" cy="12" r="2" fill="currentColor" /><circle cx="16" cy="18" r="2" fill="currentColor" />
        </svg>
        {label}
      </div>
      <p style={{ margin: "12px 0 0", fontSize: 11, color: "#241430888" }}>No CSS <code>:dragging</code> pseudo-class exists — drag the card to fire real drag events, or force the look with the <code>force</code> prop.</p>
    </div>
  );
}
